def vm_check(args):
    tried = False
    try:
        with open("/var/lib/vastai_kaalia/.tried_vm_on", 'r') as f:
            tried = f.read() == 'y'
    except:
        pass
    if not tried:
        print("pending")
        return
    try:
        with open("/var/lib/vastai_kaalia/kaalia.cfg", "r") as f:
            for line in f.readlines():
                entries = (line.split('='))
                if len(entries)==2 and entries[0].strip() == 'gpu_type' and entries[1].strip() == 'nvidia_vm':
                    print("on")
                    return
    except:
        pass
    print("off")

